// Enhanced Data Normalization with Error Handling
const items = $input.all();
const output = [];

for (const item of items) {
  const data = item.json;

  let normalized = {
    inquiry_id: `INQ-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
    timestamp: new Date().toISOString(),
    client_name: '',
    client_phone: '',
    property_interested: '',
    check_in: '',
    check_out: '',
    guests: '',
    message: '',
    channel_type: '',
    raw_data: JSON.stringify(data) // Keep raw data for debugging
  };

  try {
    // Detect and normalize Twilio SMS/WhatsApp
    if (data.From && data.Body) {
      const isWhatsApp = data.From.includes('whatsapp:');
      normalized.client_phone = data.From.replace('whatsapp:', '');
      normalized.message = data.Body || '';
      normalized.channel_type = isWhatsApp ? 'whatsapp' : 'sms';
      normalized.client_name = data.ProfileName || data.From.split('+')[1] || 'Guest';
    } 
    // Detect and normalize Telegram
    else if (data.message && data.message.from && !data.message.from.is_bot) {
      normalized.client_name = `${data.message.from.first_name || ''} ${data.message.from.last_name || ''}`.trim() || 'Guest';
      normalized.client_phone = data.message.from.id.toString();
      normalized.message = data.message.text || data.message.caption || '';
      normalized.channel_type = 'telegram';
    } 
    // Detect and normalize Google Forms
    else if (data.formData || data.name || data.client_name) {
      const formData = data.formData || data;
      normalized.client_name = formData.client_name || formData.name || '';
      normalized.client_phone = formData.client_phone || formData.phone || '';
      normalized.property_interested = formData.property_interested || formData.property || '';
      normalized.check_in = formData.check_in || '';
      normalized.check_out = formData.check_out || '';
      normalized.guests = formData.guests || formData.number_of_guests || '';
      normalized.message = formData.message || formData.additional_info || formData.comments || '';
      normalized.channel_type = 'form';
    }
    else {
      // Unknown format - log for investigation
      normalized.channel_type = 'unknown';
      normalized.message = JSON.stringify(data);
      normalized.client_name = 'Unknown Source';
    }

    // Clean up phone numbers
    if (normalized.client_phone) {
      normalized.client_phone = normalized.client_phone.trim();
    }

    // Ensure message is a string
    if (typeof normalized.message !== 'string') {
      normalized.message = JSON.stringify(normalized.message);
    }

    output.push({ json: normalized });

  } catch (error) {
    // If normalization fails, still push with error info
    normalized.error = error.message;
    normalized.channel_type = 'error';
    output.push({ json: normalized });
  }
}

return output;

