// Enhanced AI Response Parser with Fallback Logic
const items = $input.all();
const output = [];

for (const item of items) {
  try {
    const inquiryData = $('Normalize Inquiry Data').first().json;
    const aiResponseRaw = item.json.choices[0].message.content;

    // Parse AI response
    let aiResponse;
    try {
      aiResponse = JSON.parse(aiResponseRaw);
    } catch (parseError) {
      // If JSON parsing fails, create default structure
      aiResponse = {
        property_name: 'unknown',
        check_in: '',
        check_out: '',
        guests: 0,
        special_requests: '',
        requires_negotiation: false,
        mentions_party: false
      };
    }

    // Merge with inquiry data, preferring form data when available
    const merged = {
      ...inquiryData,
      property_name: inquiryData.property_interested || aiResponse.property_name || 'unknown',
      check_in: inquiryData.check_in || aiResponse.check_in || '',
      check_out: inquiryData.check_out || aiResponse.check_out || '',
      guests: inquiryData.guests || aiResponse.guests || 0,
      special_requests: aiResponse.special_requests || '',
      requires_negotiation: aiResponse.requires_negotiation || false,
      mentions_party: aiResponse.mentions_party || false,
      ai_extraction_success: true
    };

    output.push({ json: merged });

  } catch (error) {
    // If anything fails, use inquiry data as-is with error flag
    const inquiryData = $('Normalize Inquiry Data').first().json;
    output.push({ 
      json: {
        ...inquiryData,
        ai_extraction_success: false,
        extraction_error: error.message
      }
    });
  }
}

return output;

// Enhanced Routing Logic with Configuration
const items = $input.all();
const output = [];

for (const item of items) {
  try {
    const inquiryData = $('Parse AI Response').first().json;
    const availabilityData = $('Check Availability').first().json;
    const propertyConfig = item.json;

    let nextAction = 'ai_conversation';
    let designatedContact = null;
    let contactMethod = null;
    let routingReason = '';

    // PRIORITY 1: Check availability conflicts
    if (!availabilityData.is_available || !availabilityData.available) {
      if (availabilityData.conflicting_deals_count > 0 || availabilityData.conflicting_deals) {
        nextAction = 'conflict_to_contact';
        designatedContact = propertyConfig.pricing_decision_contact;
        contactMethod = propertyConfig.pricing_decision_contact_method;
        routingReason = `Booking conflict: ${availabilityData.conflicting_deals_count || 1} existing deal(s) for same dates`;
      } else {
        nextAction = 'decline_unavailable';
        routingReason = 'Property not available for requested dates';
      }
    } 
    // PRIORITY 2: Check for party mentions
    else if (inquiryData.mentions_party) {
      nextAction = 'party_to_contact';
      designatedContact = propertyConfig.party_inquiry_contact;
      contactMethod = propertyConfig.party_inquiry_contact_method;
      routingReason = 'Party/event detected in inquiry message';
    } 
    // PRIORITY 3: Check for pricing negotiation
    else if (inquiryData.requires_negotiation) {
      nextAction = 'negotiation_to_contact';
      designatedContact = propertyConfig.pricing_decision_contact;
      contactMethod = propertyConfig.pricing_decision_contact_method;
      routingReason = 'Guest inquiring about pricing/discounts';
    }
    // DEFAULT: AI handles conversation
    else {
      routingReason = 'Standard inquiry - AI will handle';
    }

    const result = {
      ...inquiryData,
      nextAction,
      designated_contact: designatedContact,
      contact_method: contactMethod,
      routing_reason: routingReason,
      availability: availabilityData,
      property_config: propertyConfig
    };

    output.push({ json: result });

  } catch (error) {
    // Fallback: if routing logic fails, default to AI conversation
    const inquiryData = $('Parse AI Response').first().json;
    output.push({ 
      json: {
        ...inquiryData,
        nextAction: 'ai_conversation',
        routing_error: error.message
      }
    });
  }
}

return output;

